    #[setter]
    fn set_sensitivity_move(&mut self, v: Float) { self.config.borrow_mut().controls.sensitivity_move = v; }
    /// Multiplier for mouse-look speed in WASD mode.
    #[getter]
    fn sensitivity_look(&self) -> Float { self.config.borrow().controls.sensitivity_look }
    #[setter]
    fn set_sensitivity_look(&mut self, v: Float) { self.config.borrow_mut().controls.sensitivity_look = v; }
    /// Multiplier for arcball orbit speed.
    #[getter]
    fn sensitivity_rotate(&self) -> Float { self.config.borrow().controls.sensitivity_rotate }
    #[setter]
    fn set_sensitivity_rotate(&mut self, v: Float) { self.config.borrow_mut().controls.sensitivity_rotate = v; }
    /// Multiplier for scroll and pinch zoom speed.
