#[pymethods]
impl DebugConfig {
    /// Print app lifecycle events: pause and camera-mode changes.
    #[getter]
    fn app(&self) -> bool { self.config.borrow().debug.app }
    #[setter]
    fn set_app(&mut self, v: bool) { self.config.borrow_mut().debug.app = v; }
    /// Print window and GPU setup: chosen surface format, adapter and device
    /// features, and **the present modes the surface supports**.
    ///
    /// Worth enabling once on any new machine -- it is how the vsync cap that
    /// invalidated a whole benchmark was identified.
    #[getter]
    fn window(&self) -> bool { self.config.borrow().debug.window }
    #[setter]
    fn set_window(&mut self, v: bool) { self.config.borrow_mut().debug.window = v; }
    /// Print per-mesh detail as meshes are uploaded.
    #[getter]
    fn window_mesh(&self) -> bool { self.config.borrow().debug.window_mesh }
    #[setter]
    fn set_window_mesh(&mut self, v: bool) { self.config.borrow_mut().debug.window_mesh = v; }
    /// **Does nothing.** The field exists and is settable from Python, but no code
    /// reads it. Left as a placeholder.
    #[getter]
    fn simulation(&self) -> bool { self.config.borrow().debug.simulation }
    #[setter]
    fn set_simulation(&mut self, v: bool) { self.config.borrow_mut().debug.simulation = v; }
    /// Time each GPU pass with timestamp queries, into `sim.gpu_timings()`.
    ///
    /// Off by default: the queries themselves are nearly free, but reading them
    /// back costs a buffer map per frame, and nothing needs it unless someone is
    /// asking where a frame goes. Silently inert where the adapter has no
    /// `TIMESTAMP_QUERY` -- `sim.gpu_timings()` returns an empty dict there.
    ///
    /// Draw the shadow/depth map as an overlay instead of leaving it offscreen.
    ///
    /// Only mirrors the main pass's depth at `msaa = 1`; above that the pass writes
    /// its own multisampled depth buffer and the debug view is not it.
    #[getter]
    fn gpu_timing(&self) -> bool { self.config.borrow().debug.gpu_timing }
    #[setter]
    fn set_gpu_timing(&mut self, v: bool) { self.config.borrow_mut().debug.gpu_timing = v; }
    /// Count what each body actually drew, with occlusion queries.
    ///
    /// The Visibility panel otherwise tests bounding boxes against the
    /// frustum, so "visible" means "could be seen", and a body wholly behind
    /// another still counts. This draws each body's box after the scene, with
    /// the depth test on and depth writes off, and asks the GPU how many
    /// samples survived. Zero means it put nothing on screen.
    ///
    /// Off by default: it costs a readback every frame, for a diagnostic.
    /// A box is a conservative stand-in for its body, so this can still call
    /// a body visible when only its box is -- the same direction the frustum
    /// test errs in.
    #[getter]
    fn occlusion_queries(&self) -> bool { self.config.borrow().debug.occlusion_queries }
    #[setter]
    fn set_occlusion_queries(&mut self, v: bool) { self.config.borrow_mut().debug.occlusion_queries = v; }
    #[getter]
    fn depth_show(&self) -> bool { self.config.borrow().debug.depth_show }
    #[setter]
    fn set_depth_show(&mut self, v: bool) { self.config.borrow_mut().debug.depth_show = v; }
    /// Free integer passed through to the shader, for one-off experiments.
    #[getter]
    fn extra(&self) -> u32 { self.config.borrow().debug.extra }
    #[setter]
    fn set_extra(&mut self, v: u32) { self.config.borrow_mut().debug.extra = v; }
    fn __repr__(&self) -> String {
        format!("{:?}", self.config.borrow().debug)
    }
}

/// The groups, as live views. Generated beside the group classes so a
/// group added to the struct appears here without anyone remembering.
#[pymethods]
impl super::config::Config {
    /// How the surface is coloured and the image encoded.
    #[getter]
    fn shading(&self) -> ShadingConfig { ShadingConfig { config: self.config.clone() } }
    /// The Sun as a light: its colour, the ambient floor, the debug cube.
    #[getter]
    fn light(&self) -> LightConfig { LightConfig { config: self.config.clone() } }
    /// The shadow map and its readback.
    #[getter]
    fn shadows(&self) -> ShadowsConfig { ShadowsConfig { config: self.config.clone() } }
    /// Facet edges drawn over or instead of the surface.
    #[getter]
    fn wireframe(&self) -> WireframeConfig { WireframeConfig { config: self.config.clone() } }
    /// The picked facet and the facet labels.
    #[getter]
    fn selection(&self) -> SelectionConfig { SelectionConfig { config: self.config.clone() } }
    /// Colouring facets from per-facet values.
    #[getter]
    fn data(&self) -> DataConfig { DataConfig { config: self.config.clone() } }
    /// The colour scale drawn for `data`.
    #[getter]
    fn colorbar(&self) -> ColorbarConfig { ColorbarConfig { config: self.config.clone() } }
    /// Reference axes, tick labels and the navigation gizmo.
    #[getter]
    fn axes(&self) -> AxesConfig { AxesConfig { config: self.config.clone() } }
    /// The shaded ground grid of the `blender` axes style.
    #[getter]
    fn grid(&self) -> GridConfig { GridConfig { config: self.config.clone() } }
    /// The text overlays.
    #[getter]
    fn hud(&self) -> HudConfig { HudConfig { config: self.config.clone() } }
    /// Frame export.
    #[getter]
    fn export(&self) -> ExportConfig { ExportConfig { config: self.config.clone() } }
    /// Mouse and keyboard sensitivities.
    #[getter]
    fn controls(&self) -> ControlsConfig { ControlsConfig { config: self.config.clone() } }
    /// The size of the image being rendered, as distinct from the window.
    #[getter]
    fn image(&self) -> ImageConfig { ImageConfig { config: self.config.clone() } }
    /// Diagnostics and console output.
    #[getter]
    fn debug(&self) -> DebugConfig { DebugConfig { config: self.config.clone() } }

    /// Old flat names, for one release: forwarded to the group they
    /// moved into, with a `DeprecationWarning` naming the new path.
    /// Table in `tools/config_renames.py`.
    fn __getattr__(slf: &Bound<'_, Self>, name: &str) -> PyResult<Py<PyAny>> {
        let py = slf.py();
        if let Some((group, new)) = renamed(name) {
            deprecated(py, name, group, new)?;
            return Ok(slf.getattr(group)?.getattr(new)?.unbind());
        }
        if MOVED_TO_APP.contains(&name) {
            return Err(pyo3::exceptions::PyAttributeError::new_err(format!(
                "config.{name} is a window property and moved to app.config.{name}"
            )));
        }
        Err(pyo3::exceptions::PyAttributeError::new_err(format!(
            "'Config' object has no attribute {name:?}"
        )))
    }

    /// The setter half of the shim. Anything not in the table takes the
    /// ordinary path, so the real setters on this class still run.
    fn __setattr__(slf: &Bound<'_, Self>, name: &str, value: Bound<'_, PyAny>) -> PyResult<()> {
        let py = slf.py();
        if let Some((group, new)) = renamed(name) {
            deprecated(py, name, group, new)?;
            return slf.getattr(group)?.setattr(new, value);
        }
        if MOVED_TO_APP.contains(&name) {
            return Err(pyo3::exceptions::PyAttributeError::new_err(format!(
                "config.{name} is a window property and moved to app.config.{name}"
            )));
        }
        // The generic path, by hand: calling `slf.setattr` here would come
        // straight back to this function.
        let key = pyo3::types::PyString::new(py, name);
        let rc = unsafe {
            pyo3::ffi::PyObject_GenericSetAttr(slf.as_ptr(), key.as_ptr(), value.as_ptr())
        };
        if rc == -1 {
            return Err(PyErr::fetch(py));
        }
        Ok(())
    }
}

